  async replaceSquareCatalog(context:TenantContext,services:ServiceRecord[],staff:StaffRecord[]){for(const value of services)requireCatalogScope(context,value);for(const value of staff)requireCatalogScope(context,value);for(const[key,value]of this.services)if(value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.provider==='square')this.services.delete(key);for(const[key,value]of this.staff)if(value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.provider==='square')this.staff.delete(key);for(const value of services)this.services.set(scope(value.tenantId,`${value.locationId}:square:${value.id}`),value);for(const value of staff)this.staff.set(scope(value.tenantId,`${value.locationId}:square:${value.id}`),value)}
