  async dispatchWorkflowJobs(event: DomainEvent, jobs: WorkflowJob[]) { if(this.dispatchedEvents.has(event.eventId))return;for(const job of jobs){if(this.workflowDedupe.has(job.dedupeKey))continue;this.workflowJobs.set(job.id,job);this.workflowDedupe.add(job.dedupeKey)}this.dispatchedEvents.add(event.eventId);this.outbox=this.outbox.filter(value=>value.eventId!==event.eventId) }
  async claimDueWorkflowJobs(workerId:string,limit:number){const now=Date.now();const jobs=[...this.workflowJobs.values()].filter(value=>(value.status==='pending'&&Date.parse(value.runAt)<=now)||(value.status==='running'&&value.lockedAt!==undefined&&Date.parse(value.lockedAt)<now-5*60_000)).sort((a,b)=>Date.parse(a.runAt)-Date.parse(b.runAt)).slice(0,limit);for(const job of jobs){job.status='running';job.attempts+=1;job.lockedBy=workerId;job.lockedAt=new Date().toISOString();job.updatedAt=job.lockedAt}return jobs}
  async completeWorkflowJob(claimed:WorkflowJob,workerId:string){const job=this.workflowJobs.get(claimed.id);if(job?.tenantId===claimed.tenantId&&job.locationId===claimed.locationId&&job.status==='running'&&job.lockedBy===workerId){job.status='completed';delete job.lockedBy;delete job.lockedAt;job.updatedAt=new Date().toISOString()}}
