  async deadLetterWorkflow(claimed:WorkflowJob,workerId:string,error:string,approval:ApprovalRequest,eventId:string){requireDeadLetterApprovalScope(claimed,approval);const job=this.workflowJobs.get(claimed.id);if(!job||job.tenantId!==claimed.tenantId||job.locationId!==claimed.locationId||job.status!=='running'||job.lockedBy!==workerId)return undefined;const existing=[...this.approvals.values()].find(item=>item.tenantId===approval.tenantId&&item.locationId===approval.locationId&&item.requestType===approval.requestType&&item.entityType===approval.entityType&&item.entityId===approval.entityId&&item.status==='pending');if(!existing&&this.events.has(eventId))throw new Error('Workflow dead-letter event evidence collision');job.status='failed';job.lastError=error.slice(0,240);delete job.lockedBy;delete job.lockedAt;job.updatedAt=approval.createdAt;const savedApproval=await this.createApprovalRequest(approval);const deadLetter:WorkflowDeadLetter={id:randomUUID(),tenantId:job.tenantId,locationId:job.locationId,workflowJobId:job.id,workflowType:job.workflowType,attempts:job.attempts,maxAttempts:job.maxAttempts,failureDetail:job.lastError,approvalId:savedApproval.id,failedAt:approval.createdAt};this.workflowDeadLetters.set(scope(job.tenantId,deadLetter.id),deadLetter);if(savedApproval.id===approval.id){const event:DomainEvent={eventId,tenantId:job.tenantId,locationId:job.locationId,eventType:'approval.requested',occurredAt:approval.createdAt,correlationId:job.correlationId,causationId:deadLetter.id,schemaVersion:1,payload:{approvalId:savedApproval.id,requestType:savedApproval.requestType,entityType:savedApproval.entityType,entityId:savedApproval.entityId,deadLetterId:deadLetter.id}};this.events.set(event.eventId,event);this.outbox.push(event)}return{approval:savedApproval,deadLetter}}
  async listWorkflowDeadLetters(context:TenantContext){return[...this.workflowDeadLetters.values()].filter(value=>value.tenantId===context.tenantId&&value.locationId===context.locationId).sort((a,b)=>Date.parse(b.failedAt)-Date.parse(a.failedAt)||b.id.localeCompare(a.id))}
