  async scheduleWeeklyReportWithEvidence(context:TenantContext,settings:LocationSettings,job:WorkflowJob,evidence:WeeklyReportScheduleEvidence){requireWeeklyReportScheduleScope(context,settings,job,evidence);const key=scope(settings.tenantId,settings.locationId);const current=this.locationSettings.get(key);if(!current||canonicalJson(settingsScheduleBase(current))!==canonicalJson(settingsScheduleBase(settings)))throw new Error('LOCATION_SETTINGS_VERSION_CONFLICT');if(this.workflowDedupe.has(job.dedupeKey))throw new Error('WEEKLY_REPORT_SCHEDULE_CONFLICT');if(this.workflowJobs.has(job.id)||this.audit.some(item=>item.id===evidence.auditId))throw new Error('Weekly report schedule evidence collision');const audit=sealScopedAudit(this.audit,weeklyReportScheduleAudit(context,job,evidence));const savedSettings=structuredClone(settings);const savedJob=structuredClone(job);this.locationSettings.set(key,savedSettings);this.workflowJobs.set(savedJob.id,savedJob);this.workflowDedupe.add(savedJob.dedupeKey);this.audit.push(audit);return{settings:structuredClone(savedSettings),job:structuredClone(savedJob)}}
