  async completeWaitlistOfferDeliveryWithEvidence(context:TenantContext,offerId:string,providerMessageId:string,expiryJob:WorkflowJob,evidence:WaitlistOfferDeliveryEvidence){requireJobScope(context,expiryJob);const offer=await this.getWaitlistOffer(context,offerId);if(!offer)throw new Error('WAITLIST_OFFER_DELIVERY_REFERENCE_MISMATCH');requireWaitlistOfferDeliveryScope(context,offer,providerMessageId,expiryJob,evidence);if(offer.sentAt)return{offer:structuredClone(offer),duplicate:true};const entry=this.waitlistEntries.get(scope(context.tenantId,offer.entryId));if(offer.status!=='offered'||!entry||entry.locationId!==context.locationId||entry.status!=='offered'||entry.channel!==offer.channel)throw new Error('WAITLIST_OFFER_DELIVERY_TRANSITION_CONFLICT');if(this.workflowJobs.has(expiryJob.id)||this.workflowDedupe.has(expiryJob.dedupeKey)||this.events.has(evidence.eventId)||this.audit.some(item=>item.id===evidence.auditId))throw new Error('Waitlist offer delivery evidence collision');const delivered:WaitlistOffer={...offer,sentAt:evidence.occurredAt,providerMessageId};const event=waitlistOfferDeliveredEvent(delivered,evidence);const audit=sealScopedAudit(this.audit,waitlistOfferDeliveredAudit(context,delivered,evidence));this.waitlistOffers.set(scope(context.tenantId,offer.id),delivered);this.workflowJobs.set(expiryJob.id,structuredClone(expiryJob));this.workflowDedupe.add(expiryJob.dedupeKey);this.events.set(event.eventId,event);this.outbox.push(event);this.audit.push(audit);return{offer:structuredClone(delivered),duplicate:false}}
