  async expireWaitlistOfferWithEvidence(context:TenantContext,offerId:string,continuationJob:WorkflowJob,evidence:WaitlistOfferTransitionEvidence){const offer=await this.getWaitlistOffer(context,offerId);if(!offer)return undefined;if(offer.status==='expired')return{offer:structuredClone(offer),duplicate:true};if(!['offered','accepted'].includes(offer.status))return undefined;requireWaitlistOfferTransitionScope(context,offer,'expired',continuationJob,evidence);const entry=this.waitlistEntries.get(scope(context.tenantId,offer.entryId));const expectedEntryStatus=offer.status==='accepted'?'matched':'offered';if(!entry||entry.locationId!==context.locationId||entry.status!==expectedEntryStatus)throw new Error('WAITLIST_OFFER_EXPIRY_TRANSITION_CONFLICT');if(this.events.has(evidence.eventId)||this.audit.some(item=>item.id===evidence.auditId)||this.workflowJobs.has(continuationJob.id)||this.workflowDedupe.has(continuationJob.dedupeKey))throw new Error('Waitlist offer expiry evidence collision');const expired:WaitlistOffer={...offer,status:'expired',expiredAt:evidence.occurredAt};const updatedEntry:WaitlistEntry={...entry,status:'active'};const event=waitlistOfferTransitionEvent(expired,evidence);const audit=sealScopedAudit(this.audit,waitlistOfferTransitionAudit(context,expired,true,evidence));this.waitlistOffers.set(scope(context.tenantId,offer.id),expired);this.waitlistEntries.set(scope(context.tenantId,entry.id),updatedEntry);this.workflowJobs.set(continuationJob.id,structuredClone(continuationJob));this.workflowDedupe.add(continuationJob.dedupeKey);this.events.set(event.eventId,event);this.outbox.push(event);this.audit.push(audit);return{offer:structuredClone(expired),duplicate:false}}
  async completeWaitlistRecovery(context:TenantContext,offerId:string,booking:BookingRecord,attribution:RevenueAttribution){const offer=await this.getWaitlistOffer(context,offerId);const entry=offer?this.waitlistEntries.get(scope(context.tenantId,offer.entryId)):undefined;if(offer?.status==='booked'&&[...this.revenue.values()].some(value=>value.bookingId===booking.id&&value.attributionType==='waitlist_fill'))return;if(!offer||offer.status!=='accepted'||!entry||entry.clientId!==booking.clientId||offer.serviceId!==booking.serviceId||offer.staffId!==booking.staffId||offer.startsAt!==booking.startsAt)throw new Error('Waitlist offer does not match the booking');offer.status='booked';entry.status='booked';this.revenue.set(scope(context.tenantId,attribution.id),attribution)}
