  async listRecoveryAttributionTouches(context:TenantContext,clientId:string,before:string){const cutoff=Date.parse(before),after=cutoff-30*86_400_000;const touches:RecoveryAttributionTouch[]=[];for(const value of this.recoveryContacts.values())if(value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.clientId===clientId&&value.status==='sent'&&value.sentAt&&Date.parse(value.sentAt)<=cutoff&&Date.parse(value.sentAt)>after){const recovery=[...this.recoveryCases.values()].find(item=>item.tenantId===context.tenantId&&item.locationId===context.locationId&&item.workflowJobId===value.workflowJobId);touches.push({sourceType:value.workflowType,sourceId:value.id,workflowJobId:value.workflowJobId,clientId,occurredAt:value.sentAt,...(recovery?{recoveryCorrelationId:recovery.correlationId}:{})})}for(const value of this.conversationFollowups.values())if(value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.clientId===clientId&&value.status==='sent'&&value.sentAt&&Date.parse(value.sentAt)<=cutoff&&Date.parse(value.sentAt)>after)touches.push({sourceType:'abandoned_enquiry',sourceId:value.id,workflowJobId:value.workflowJobId,clientId,occurredAt:value.sentAt});for(const value of this.missedCallRecoveries.values())if(value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.clientId===clientId&&value.status==='sent'&&value.sentAt&&Date.parse(value.sentAt)<=cutoff&&Date.parse(value.sentAt)>after)touches.push({sourceType:'missed_call_recovery',sourceId:value.id,workflowJobId:value.workflowJobId,clientId,occurredAt:value.sentAt});return touches.sort((a,b)=>Date.parse(b.occurredAt)-Date.parse(a.occurredAt)||a.sourceType.localeCompare(b.sourceType)||a.sourceId.localeCompare(b.sourceId))}
