  async reserveRecoveryContact(context:TenantContext,job:WorkflowJob,clientId:string,channel:'sms'|'whatsapp'='sms'){requireJobScope(context,job);const existing=[...this.recoveryContacts.values()].find(value=>value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.workflowJobId===job.id);if(existing){if(existing.channel!==channel)throw new Error('RECOVERY_CONTACT_CHANNEL_MISMATCH');return{allowed:true,attempt:existing}}const sent=[...this.recoveryContacts.values()].filter(value=>value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.clientId===clientId&&value.status==='sent'&&value.sentAt).sort((a,b)=>Date.parse(b.sentAt!)-Date.parse(a.sentAt!));if(sent[0]&&Date.parse(sent[0].sentAt!)>Date.now()-7*86_400_000)return{allowed:false,reason:'seven_day_interval' as const};if(sent.filter(value=>Date.parse(value.sentAt!)>Date.now()-30*86_400_000).length>=2)return{allowed:false,reason:'thirty_day_cap' as const};if(!['no_show_recovery','post_visit_rebook','lapsed_reactivation'].includes(job.workflowType))throw new Error('Invalid recovery workflow type');const attempt:RecoveryContactAttempt={id:randomUUID(),tenantId:context.tenantId,locationId:context.locationId,workflowJobId:job.id,clientId,workflowType:job.workflowType as RecoveryContactAttempt['workflowType'],channel,status:'reserved',reservedAt:new Date().toISOString()};this.recoveryContacts.set(attempt.id,attempt);return{allowed:true,attempt}}
