  async saveExperiment(value:ControlledExperiment){this.experiments.set(scope(value.tenantId,value.id),value);return value}
  async createExperiment(value:ControlledExperiment,evidence:ExperimentCreationEvidence){if(value.createdBy!==evidence.userId||value.updatedBy!==evidence.userId||value.createdAt!==evidence.occurredAt||value.updatedAt!==evidence.occurredAt)throw new Error('EXPERIMENT_CREATION_SCOPE_MISMATCH');if(this.experiments.has(scope(value.tenantId,value.id))||this.audit.some(item=>item.id===evidence.auditId))throw new Error('Experiment creation evidence collision');const scoped=this.audit.filter(item=>item.tenantId===value.tenantId&&item.locationId===value.locationId);const chained=scoped.filter(isChained).sort((a,b)=>a.sequence-b.sequence);const head=chained.at(-1);const audit=sealAuditRecord(experimentCreationAudit(value,evidence),(head?.sequence??0)+1,head?.recordHash??(scoped.length?legacyAuditAnchor(scoped):AUDIT_GENESIS_HASH));this.experiments.set(scope(value.tenantId,value.id),value);this.audit.push(audit);return value}
