  async buildClientDataSnapshot(context:TenantContext,clientId:string):Promise<ClientDataSnapshot>{
    const scoped=<T extends{tenantId:string;locationId:string}>(values:Iterable<T>)=>[...values].filter(value=>value.tenantId===context.tenantId&&value.locationId===context.locationId)
    const conversations=scoped(this.conversations.values()).filter(value=>value.clientId===clientId)
    const conversationIds=new Set(conversations.map(value=>value.id))
    return structuredClone({
      profile:this.clientProfiles.get(scope(context.tenantId,`${context.locationId}:${clientId}`))??null,
      consents:scoped(this.consents.values()).filter(value=>value.clientId===clientId),
      holds:scoped(this.holds.values()).filter(value=>value.clientId===clientId),
      bookings:scoped(this.bookings.values()).filter(value=>value.clientId===clientId),
      waitlistEntries:scoped(this.waitlistEntries.values()).filter(value=>value.clientId===clientId),
      conversations,
      messages:scoped(this.conversationMessages.values()).filter(value=>conversationIds.has(value.conversationId)),
      reviewRequests:scoped(this.reviewRequests.values()).filter(value=>value.clientId===clientId),
      recoveryContacts:scoped(this.recoveryContacts.values()).filter(value=>value.clientId===clientId),
      conversationFollowups:scoped(this.conversationFollowups.values()).filter(value=>value.clientId===clientId),
      missedCallRecoveries:scoped(this.missedCallRecoveries.values()).filter(value=>value.clientId===clientId),
      messageDeliveries:scoped(this.outboundDeliveries.values()).filter(value=>value.clientId===clientId),
      events:scoped(this.events.values()).filter(value=>value.payload.clientId===clientId),
      auditRecords:this.audit.filter(value=>value.tenantId===context.tenantId&&value.locationId===context.locationId&&value.entityType==='client'&&value.entityId===clientId),
    })
  }
