function circuitKey(context:Pick<TenantContext,'tenantId'|'locationId'>,provider:ProviderName){return`${context.tenantId}:${context.locationId}:${provider}`}
function requireHoldCreationScope(context:TenantContext,value:AppointmentHold,evidence:HoldCreationEvidence){if(value.tenantId!==context.tenantId||value.locationId!==context.locationId||value.status!=='active'||value.bookingAttemptKey!==undefined||evidence.userId!==context.userId||Date.parse(value.expiresAt)-Date.parse(evidence.occurredAt)!==10*60_000)throw new Error('HOLD_CREATION_SCOPE_MISMATCH')}
function requireToolCallScope(context:TenantContext,value:ToolCallRecord,evidence:ToolCallEvidence){if(value.tenantId!==context.tenantId||value.locationId!==context.locationId||evidence.userId!==context.userId||value.completedAt!==evidence.occurredAt||!Number.isFinite(Date.parse(value.createdAt))||!Number.isFinite(Date.parse(value.completedAt))||Date.parse(value.completedAt)<Date.parse(value.createdAt)||!value.providerCallId||!value.agentRunId)throw new Error('TOOL_CALL_SCOPE_MISMATCH')}
function toolCallAudit(context:TenantContext,value:ToolCallRecord,evidence:ToolCallEvidence):AuditRecordInput{return{id:evidence.auditId,tenantId:context.tenantId,locationId:context.locationId,userId:evidence.userId,action:`booking_tool.${value.status}`,entityType:'tool_call',entityId:value.id,reason:`Booking specialist ${value.toolName} call ${value.status}`,input:value.input,result:{conversationId:value.conversationId,agentRunId:value.agentRunId,toolName:value.toolName,status:value.status,...(value.errorCode?{errorCode:value.errorCode}:{})},occurredAt:evidence.occurredAt}}
function requireRecoveryCaseOpeningScope(context:TenantContext,value:RecoveryCase,evidence:RecoveryCaseOpeningEvidence){if(context.role!=='service'||value.tenantId!==context.tenantId||value.locationId!==context.locationId||value.status!=='open'||value.openedAt!==evidence.occurredAt||evidence.userId!==context.userId||!context.userId.startsWith('workflow:')||!value.workflowJobId||!value.correlationId||!evidence.causationId||value.resolvedAt||value.resultBookingId||value.closeReason||!Number.isFinite(Date.parse(value.openedAt))||(value.potentialRevenueMinor!==undefined&&!Number.isInteger(value.potentialRevenueMinor))||(value.currency!==undefined&&!/^[A-Z]{3}$/.test(value.currency)))throw new Error('RECOVERY_CASE_OPENING_SCOPE_MISMATCH')}
function recoveryCaseOpenedEvent(value:RecoveryCase,evidence:RecoveryCaseOpeningEvidence):DomainEvent{return{eventId:evidence.eventId,tenantId:value.tenantId,locationId:value.locationId,eventType:'recovery.opened',occurredAt:evidence.occurredAt,correlationId:value.correlationId,causationId:evidence.causationId,schemaVersion:1,payload:{recoveryCaseId:value.id,recoveryType:value.recoveryType,workflowJobId:value.workflowJobId}}}
