function requireRecoveryCaseClosureScope(context:TenantContext,correlationId:string,reason:RecoveryCaseCloseReason,evidence:RecoveryCaseClosureEvidence){if(context.role!=='service'||!context.userId.startsWith('workflow:')||evidence.userId!==context.userId||correlationId.length<3||!['already_booked','seven_day_interval','thirty_day_cap','frequency_cap','waitlist_exhausted'].includes(reason)||!evidence.causationId||!Number.isFinite(Date.parse(evidence.occurredAt)))throw new Error('RECOVERY_CASE_CLOSURE_SCOPE_MISMATCH')}
